INSERT INTO `what_announcements` VALUES (1, '中央机关及其直属机构2026年度考试录用公务员公告', 'https://www.scs.gov.cn/ks/202510/12345.html', '国家公务员局', '2025-10-15', '根据公务员法和公务员录用规定等法律法规，国家公务员局将组织实施中央机关及其直属机构2026年度考试录用一级主任科员及以下和其他相当职级层次公务员工作...', '招录公告', '国考', NULL, NULL, NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
INSERT INTO `what_announcements` VALUES (2, '2026年度国家公务员考试报名统计（10月25日）', 'https://www.scs.gov.cn/ks/202510/12346.html', '国家公务员局', '2025-10-25', '截至2025年10月25日18:00，共有156万人报名，已通过资格审查人数为145万人，竞争最激烈岗位为国家统计局某职位，竞争比达3521:1...', '报名统计', '国考', NULL, NULL, NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
INSERT INTO `what_announcements` VALUES (3, '广东省2026年考试录用公务员公告', 'https://www.gdhrss.gov.cn/ks/202512/67890.html', '广东省人力资源和社会保障厅', '2025-12-10', '为满足全省各级机关补充公务员的需要，根据公务员法和公务员录用规定等法律法规，广东省公务员局将组织实施2026年全省各级机关考试录用公务员工作...', '招录公告', '省考', '广东省', NULL, NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
INSERT INTO `what_announcements` VALUES (4, '浙江省2026年考试录用公务员公告', 'https://www.zjhrss.gov.cn/ks/202512/11111.html', '浙江省人力资源和社会保障厅', '2025-12-08', '根据《中华人民共和国公务员法》等法律法规，浙江省公务员局将组织实施2026年全省各级机关和参照公务员法管理单位考试录用公务员工作...', '招录公告', '省考', '浙江省', NULL, NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
INSERT INTO `what_announcements` VALUES (5, '2026年上海市事业单位公开招聘工作人员公告', 'https://www.shhrss.gov.cn/ks/202601/22222.html', '上海市人力资源和社会保障局', '2026-01-05', '为进一步优化事业单位人才队伍结构，根据《事业单位人事管理条例》等有关规定，上海市将面向社会公开招聘事业单位工作人员...', '招录公告', '事业单位', '上海市', '上海市', NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
INSERT INTO `what_announcements` VALUES (6, '北京市2026年选调应届优秀大学毕业生公告', 'https://www.bjhrss.gov.cn/ks/202512/33333.html', '北京市委组织部', '2025-12-15', '为加强党政机关后备干部队伍建设，选拔优秀年轻干部人才，根据有关规定，北京市将选调2026年应届优秀大学毕业生到北京市各级党政机关工作...', '招录公告', '选调生', '北京市', '北京市', NULL, 1, '2026-01-24 14:47:16.000', '2026-01-24 14:47:16.000', NULL);
