INSERT INTO `what_course_categories` VALUES (2, 1, '1.1 言语理解与表达课程', 'cat_7b2ae94e', '', '', '', '#6366f1', '', 0, 1, 2, '1', 0, '2026-01-28 20:26:22.654', '2026-01-28 20:26:22.654', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `what_course_categories` VALUES (3, 2, '实词辨析精讲（20课时）', 'cat_4414a767', '', '', '', '#6366f1', '', 0, 1, 3, '1/2', 0, '2026-01-28 20:26:22.660', '2026-01-28 20:26:22.660', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, NULL);
INSERT INTO `what_course_categories` VALUES (546, NULL, '言语理解与表达', 'xingce_yanyu', '', 'xingce', 'BookText', 'from-sky-500 to-cyan-600', '系统学习言语理解与表达，包括逻辑填空、片段阅读、语句表达三大模块，全面提升语言理解与运用能力。', 10, 1, 1, '', 234, '2026-01-29 03:18:11.680', '2026-01-29 03:18:11.680', NULL, '言语理解与表达是行测考试的重要组成部分，主要考查考生对语言文字的理解和运用能力。本课程体系涵盖逻辑填空（实词辨析、成语辨析、关联词）、片段阅读（主旨概括、意图判断、细节理解、标题选择）、语句表达（语句排序、语句填空）三大模块，通过系统学习帮助考生全面提升言语理解能力。', '[]', '[]', '[]', '', '', 40, 35, 25, '[]');
INSERT INTO `what_course_categories` VALUES (547, 546, '逻辑填空', 'xingce_luoji_tiankong', '', 'xingce', '', '#6366f1', '系统学习逻辑填空题型，掌握语境分析、词义辨析、关联词搭配等核心方法。', 10, 1, 2, '', 70, '2026-01-29 03:18:11.681', '2026-01-29 03:18:11.681', NULL, '逻辑填空是言语理解的核心题型，主要考查考生对语境的理解与词汇的准确把握。本课程体系涵盖语境分析（上下文逻辑关系、情感色彩倾向）、词义辨析（实词辨析、成语辨析）、关联词搭配（复句关系、逻辑衔接），帮助考生准确选择最佳词语。', '[]', '[]', '[]', '45课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (548, 547, '实词辨析精讲', 'xingce_shici_bianxi', '', 'xingce', '', '#6366f1', '系统学习实词辨析，掌握语素分析、语境推断、感情色彩辨析等核心方法。', 10, 1, 3, '', 19, '2026-01-29 03:18:11.681', '2026-01-29 03:18:11.681', NULL, '实词辨析是逻辑填空的基础内容，主要考查考生对实词含义的理解和辨析能力。本课程体系涵盖语素分析法（拆解词语理解含义）、语境推断法（根据上下文判断用词）、感情色彩辨析（褒义、贬义、中性）、语义轻重辨析、搭配习惯等核心方法。', '[]', '[]', '[]', '20课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (549, 547, '成语辨析精讲', 'xingce_chengyu_bianxi', '', 'xingce', '', '#6366f1', '系统学习成语辨析，掌握高频成语含义、易混成语区分、成语误用类型等核心内容。', 20, 1, 3, '', 25, '2026-01-29 03:18:11.688', '2026-01-29 03:18:11.688', NULL, '成语辨析是逻辑填空的重要内容，主要考查考生对成语含义的理解和正确使用能力。本课程体系涵盖高频成语讲解（800+必考成语）、易混成语区分（近义成语辨析）、成语误用类型（望文生义、对象误用、语义重复等），帮助考生准确使用成语。', '[]', '[]', '[]', '15课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (550, 547, '关联词精讲', 'xingce_guanlian_ci', '', 'xingce', '', '#6366f1', '系统学习关联词，掌握关联词的分类、搭配规则与逻辑关系判断方法。', 30, 1, 3, '', 11, '2026-01-29 03:18:11.693', '2026-01-29 03:18:11.693', NULL, '关联词是逻辑填空的重要考点，主要考查考生对句间逻辑关系的判断能力。本课程体系涵盖关联词分类（转折、因果、递进、并列、条件、假设）、搭配规则（固定搭配、正确使用）、逻辑关系判断（根据句意选择关联词），帮助考生准确把握句间关系。', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (551, 546, '片段阅读', 'xingce_pianduan_yuedu', '', 'xingce', '', '#6366f1', '系统学习片段阅读题型，掌握主旨概括、意图判断、细节判断、标题选择等核心方法。', 20, 1, 2, '', 86, '2026-01-29 03:18:11.696', '2026-01-29 03:18:11.696', NULL, '片段阅读是言语理解的核心题型，主要考查考生对文段的理解与分析能力。本课程体系涵盖主旨概括（中心句定位、归纳概括）、意图判断（作者态度、言外之意）、细节判断（信息匹配、选项辨析）、标题选择（主旨提炼、标题特点），帮助考生准确把握文段核心。', '[]', '[]', '[]', '40课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (552, 551, '主旨概括精讲', 'xingce_zhuzhi_gaigua', '', 'xingce', '', '#6366f1', '系统学习主旨概括题型，掌握行文脉络分析、关键句识别、主旨归纳等核心方法。', 10, 1, 3, '', 12, '2026-01-29 03:18:11.696', '2026-01-29 03:18:11.696', NULL, '主旨概括是片段阅读的核心题型，主要考查考生对文段主旨的概括能力。本课程体系涵盖行文脉络分析（总分、分总、总分总等结构）、关键句识别（首尾句、转折句、总结句）、主旨归纳方法（提炼核心观点）、干扰项排除（过于绝对、无中生有等），帮助考生准确把握文段主旨。', '[]', '[]', '[]', '15课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (553, 551, '意图判断精讲', 'xingce_yitu_panduan', '', 'xingce', '', '#6366f1', '系统学习意图判断题型，掌握揣摩作者意图、把握言外之意的核心方法。', 20, 1, 3, '', 12, '2026-01-29 03:18:11.702', '2026-01-29 03:18:11.702', NULL, '意图判断是片段阅读的重要题型，主要考查考生对作者写作意图的理解能力。本课程体系涵盖意图判断基本方法（揣摩作者真实用意）、与主旨题的区分（字面意思vs言外之意）、典型题型训练（呼吁建议类、警示类等），帮助考生准确把握作者意图。', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (554, 551, '细节理解精讲', 'xingce_xijie_lijie', '', 'xingce', '', '#6366f1', '系统学习细节理解题型，掌握精准定位、对比验证、排除干扰的核心技巧。', 30, 1, 3, '', 11, '2026-01-29 03:18:11.708', '2026-01-29 03:18:11.708', NULL, '细节理解是片段阅读的基础题型，主要考查考生对文段细节信息的把握能力。本课程体系涵盖细节判断基本方法（定位原文、对比选项）、干扰项识别（偷换概念、以偏概全、无中生有）、快速定位技巧（关键词匹配、跳读法），帮助考生准确判断细节正误。', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (555, 551, '标题选择精讲', 'xingce_biaoti_xuanze', '', 'xingce', '', '#6366f1', '系统学习语句表达题型，掌握语句排序、语句衔接、下文推断等核心方法。', 40, 1, 3, '', 13, '2026-01-29 03:18:11.713', '2026-01-29 03:18:11.713', NULL, '语句表达是言语理解的特色题型，主要考查考生对语句逻辑关系的理解能力。本课程体系涵盖语句排序（首尾句特征、逻辑关系、关联词衔接）、语句衔接（话题一致、逻辑连贯）、下文推断（尾句分析、内容预测），帮助考生理顺语句逻辑关系。', '[]', '[]', '[]', '5课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (556, 546, '语句表达', 'xingce_yuju_biaoda', '', 'xingce', '', '#6366f1', '系统学习语句表达，掌握语句排序、语句填空等题型的解题技巧。', 30, 1, 2, '', 29, '2026-01-29 03:18:11.716', '2026-01-29 03:18:11.716', NULL, '语句表达是言语理解与表达的重要组成部分，主要考查考生的语句组织和表达能力。本课程体系涵盖语句排序（首尾句判断、关键词衔接、逻辑顺序）、语句填空（总结句、过渡句、引领句）等题型，帮助考生快速理清句间关系，准确完成语句组织。', '[]', '[]', '[]', '13课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (557, 556, '语句排序精讲', 'xingce_yuju_paixu', '', 'xingce', '', '#6366f1', '掌握语句排序的核心方法', 10, 1, 3, '', 9, '2026-01-29 03:18:11.716', '2026-01-29 03:18:11.716', NULL, '', '[]', '[]', '[]', '8课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (558, 556, '语句填空精讲', 'xingce_yuju_tiankong', '', 'xingce', '', '#6366f1', '掌握语句填空的解题技巧', 20, 1, 3, '', 8, '2026-01-29 03:18:11.720', '2026-01-29 03:18:11.720', NULL, '', '[]', '[]', '[]', '5课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (559, NULL, '数量关系', 'xingce_shuliang', '', 'xingce', 'Calculator', 'from-violet-500 to-purple-600', '系统学习数量关系，包括数学运算和数字推理两大模块，掌握各类题型的解题方法与速算技巧。', 20, 1, 1, '', 131, '2026-01-29 03:18:11.723', '2026-01-29 03:18:11.723', NULL, '数量关系是行测考试中难度较高的部分，主要考查考生的数学运算能力和数字规律推理能力。本课程体系涵盖数学运算（计算技巧、行程问题、工程问题、利润问题、排列组合、概率问题、几何问题等）和数字推理（等差等比数列、递推数列、特殊数列等）两大模块，帮助考生掌握各类题型的解题方法。', '[]', '[]', '[]', '', '', 15, 25, 15, '[]');
INSERT INTO `what_course_categories` VALUES (560, 559, '数学运算', 'xingce_shuxue_yunsuan', '', 'xingce', '', '#6366f1', '系统学习数学运算题型，掌握方程法、比例法、特值法等核心解题方法。', 10, 1, 2, '', 111, '2026-01-29 03:18:11.723', '2026-01-29 03:18:11.723', NULL, '数学运算是数量关系的核心题型，主要考查考生的数学思维与计算能力。本课程体系涵盖基础解题方法（方程法、比例法、特值法、代入排除法）、核心题型（工程问题、行程问题、利润问题、排列组合、概率问题），帮助考生快速准确解题。', '[]', '[]', '[]', '66课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (561, 560, '计算问题与技巧', 'xingce_jisuan_jiqiao', '', 'xingce', '', '#6366f1', '', 10, 1, 3, '', 3, '2026-01-29 03:18:11.724', '2026-01-29 03:18:11.724', NULL, '', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (562, 560, '行程问题精讲', 'xingce_xingcheng_wenti', '', 'xingce', '', '#6366f1', '系统学习行程问题，掌握相遇追及、流水行船、环形跑道等典型题型解题方法。', 20, 1, 3, '', 9, '2026-01-29 03:18:11.728', '2026-01-29 03:18:11.728', NULL, '行程问题是数学运算的经典题型，主要考查路程、速度、时间三者关系的应用能力。本课程体系涵盖相遇与追及问题（同向与反向运动）、流水行船问题（顺流逆流速度关系）、环形跑道问题（圆周运动规律）、火车过桥问题、钟表问题等，全面攻克行程问题所有考点。', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (563, 560, '工程问题精讲', 'xingce_gongcheng_wenti', '', 'xingce', '', '#6366f1', '系统学习工程问题，掌握效率、时间、总量关系及合作、轮换工程解题方法。', 30, 1, 3, '', 9, '2026-01-29 03:18:11.732', '2026-01-29 03:18:11.732', NULL, '工程问题是数学运算的基础题型，主要考查工作效率、工作时间、工作总量三者关系的应用能力。本课程体系涵盖工程问题基础（三要素关系）、合作工程（多人合作完成）、轮换工程（交替工作模式）、变速工程（效率变化问题），帮助考生建立完整的工程问题解题体系。', '[]', '[]', '[]', '8课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (564, 560, '利润问题精讲', 'xingce_lirun_wenti', '', 'xingce', '', '#6366f1', '', 40, 1, 3, '', 9, '2026-01-29 03:18:11.736', '2026-01-29 03:18:11.736', NULL, '', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (565, 560, '排列组合精讲', 'xingce_pailie_zuhe', '', 'xingce', '', '#6366f1', '系统学习排列组合，掌握加法乘法原理、排列组合公式及典型模型应用。', 50, 1, 3, '', 12, '2026-01-29 03:18:11.739', '2026-01-29 03:18:11.739', NULL, '排列组合是数学运算的难点题型，主要考查计数原理的应用能力。本课程体系涵盖基本原理（加法原理与乘法原理）、排列组合公式（P与C的计算与选用）、典型模型（隔板法、环形排列、捆绑法、插空法、错位重排），全面攻克排列组合所有考点。', '[]', '[]', '[]', '12课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (566, 560, '概率问题精讲', 'xingce_gailv_wenti', '', 'xingce', '', '#6366f1', '', 60, 1, 3, '', 11, '2026-01-29 03:18:11.743', '2026-01-29 03:18:11.743', NULL, '', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
