INSERT INTO `what_course_categories` VALUES (569, 559, '数字推理', 'xingce_shuzi_tuili', '', 'xingce', '', '#6366f1', '系统学习数字推理，掌握等差数列、等比数列、递推数列、特殊数列等核心规律。', 20, 1, 2, '', 31, '2026-01-29 03:18:11.753', '2026-01-29 03:18:11.753', NULL, '数字推理是数量关系的规律识别题型，主要考查考生对数列规律的识别与推理能力。本课程体系涵盖基础数列（等差、等比、质数、合数）、递推数列（和数列、积数列、差数列）、特殊数列（幂次数列、分数数列、多重数列），帮助考生快速识别数列规律。', '[]', '[]', '[]', '16课时', '', 0, 0, 0, '[]');
