INSERT INTO `what_course_categories` VALUES (573, NULL, '判断推理', 'xingce_panduan', '', 'xingce', 'Brain', 'from-emerald-500 to-teal-600', '系统学习判断推理，包括图形推理、定义判断、类比推理、逻辑判断四大模块，培养逻辑思维与分析判断能力。', 30, 1, 1, '', 167, '2026-01-29 03:18:11.759', '2026-01-29 03:18:11.759', NULL, '判断推理是行测考试中题量较大的部分，主要考查考生的逻辑思维能力和分析判断能力。本课程体系涵盖图形推理（位置规律、样式规律、属性规律、数量规律、空间重构）、定义判断（核心成分法、列举排除法）、类比推理（语义关系、逻辑关系、语法关系）、逻辑判断（翻译推理、真假推理、分析推理、加强削弱）四大模块。', '[]', '[]', '[]', '', '', 40, 35, 25, '[]');
INSERT INTO `what_course_categories` VALUES (574, 573, '图形推理', 'xingce_tuxing_tuili', '', 'xingce', '', '#6366f1', '系统学习图形推理题型，掌握位置、样式、属性、数量、空间重构等规律识别。', 10, 1, 2, '', 66, '2026-01-29 03:18:11.760', '2026-01-29 03:18:11.760', NULL, '图形推理是判断推理的视觉化题型，主要考查考生对图形规律的识别与推理能力。本课程体系涵盖位置规律（平移、旋转、翻转）、样式规律（遍历、叠加、组合）、属性规律（对称、封闭、曲直）、数量规律（点、线、面、角的数量变化）、空间重构（折纸盒、截面图），全面覆盖图形推理所有考点。', '[]', '[]', '[]', '30课时', '', 0, 0, 0, '[]');
