INSERT INTO `what_course_categories` VALUES (580, 573, '定义判断', 'xingce_dingyi_panduan', '', 'xingce', '', '#6366f1', '系统学习定义判断题型，掌握定义理解、要素匹配、常见类型辨析等核心方法。', 20, 1, 2, '', 29, '2026-01-29 03:18:11.775', '2026-01-29 03:18:11.775', NULL, '定义判断是判断推理的基础题型，主要考查考生对定义的理解与应用能力。本课程体系涵盖定义判断基本方法（抓核心要素、排除明显错误）、定义要素匹配（主体、客体、方式、目的等要素对应）、常见定义类型（法律、管理、心理、经济等领域定义），帮助考生准确判断定义适用情况。', '[]', '[]', '[]', '14课时', '', 0, 0, 0, '[]');
