INSERT INTO `what_course_categories` VALUES (583, 573, '类比推理', 'xingce_leibi_tuili', '', 'xingce', '', '#6366f1', '系统学习类比推理题型，掌握语义关系、逻辑关系、语法关系的识别与应用。', 30, 1, 2, '', 34, '2026-01-29 03:18:11.782', '2026-01-29 03:18:11.782', NULL, '类比推理是判断推理的快速得分题型，主要考查考生对词语关系的识别能力。本课程体系涵盖语义关系（近义、反义、比喻、象征）、逻辑关系（包含、交叉、并列、因果、条件）、语法关系（主谓、动宾、偏正），帮助考生快速准确识别词语间关系。', '[]', '[]', '[]', '10课时', '', 0, 0, 0, '[]');
