INSERT INTO `what_course_categories` VALUES (587, 573, '逻辑判断', 'xingce_luoji_panduan', '', 'xingce', '', '#6366f1', '系统学习逻辑判断题型，掌握翻译推理、真假推理、分析推理、加强削弱等核心内容。', 40, 1, 2, '', 78, '2026-01-29 03:18:11.787', '2026-01-29 03:18:11.787', NULL, '逻辑判断是判断推理的核心难点，主要考查考生的逻辑思维与论证分析能力。本课程体系涵盖翻译推理（充分必要条件转化）、真假推理（矛盾关系、反对关系）、分析推理（排列组合问题）、加强削弱（论证结构分析、加强削弱方式），全面提升逻辑推理能力。', '[]', '[]', '[]', '30课时', '', 0, 0, 0, '[]');
