INSERT INTO `what_course_categories` VALUES (592, NULL, '资料分析', 'xingce_ziliao', '', 'xingce', 'BarChart', 'from-orange-500 to-amber-600', '系统学习资料分析，掌握统计术语、计算公式与速算技巧，提升数据处理与分析能力。', 40, 1, 1, '', 103, '2026-01-29 03:18:11.803', '2026-01-29 03:18:11.803', NULL, '资料分析是行测考试中相对容易得分的部分，主要考查考生对文字、表格、图形等资料的理解与计算能力。本课程体系涵盖核心概念（增长问题、比重问题、倍数问题、平均数问题）、速算技巧（截位直除、特征数字、有效数字、同位比较）、材料类型（文字材料、表格材料、图形材料）三大模块。', '[]', '[]', '[]', '', '', 20, 25, 20, '[]');
INSERT INTO `what_course_categories` VALUES (593, 592, '核心概念', 'xingce_hexin_gainian', '', 'xingce', '', '#6366f1', '系统学习资料分析核心概念，掌握增长、比重、倍数、平均数等关键指标的计算方法。', 10, 1, 2, '', 104, '2026-01-29 03:18:11.803', '2026-01-29 03:18:11.803', NULL, '核心概念是资料分析的基础，主要考查考生对统计指标的理解与计算能力。本课程体系涵盖增长问题（增长率、增长量、年均增长）、比重问题（现期比重、基期比重、比重变化）、倍数问题（现期倍数、基期倍数）、平均数问题（平均数计算、平均数增长率），建立完整的概念体系。', '[]', '[]', '[]', '24课时', '', 0, 0, 0, '[]');
