INSERT INTO `what_course_categories` VALUES (598, 592, '速算技巧', 'xingce_susuan_jiqiao', '', 'xingce', '', '#6366f1', '系统学习速算技巧，掌握截位直除、特征数字、有效数字、同位比较等高效计算方法。', 20, 1, 2, '', 29, '2026-01-29 03:18:11.820', '2026-01-29 03:18:11.820', NULL, '速算技巧是资料分析的核心能力，决定答题速度与准确率。本课程体系涵盖截位直除法（保留有效数字快速计算）、特征数字法（利用特殊数字简化计算）、有效数字法（保留有效位数估算）、同位比较法（通过同位数字判断大小），全面提升计算速度。', '[]', '[]', '[]', '11课时', '', 0, 0, 0, '[]');
