INSERT INTO `what_course_categories` VALUES (603, 592, '材料解读', 'xingce_cailiao_jiedu', '', 'xingce', '', '#6366f1', '系统学习材料解读技巧，掌握文字、表格、图形等不同材料类型的快速解读方法。', 30, 1, 2, '', 18, '2026-01-29 03:18:11.827', '2026-01-29 03:18:11.827', NULL, '材料解读是资料分析的基础能力，决定信息定位的速度与准确性。本课程体系涵盖文字材料解读（关键词定位、段落结构分析）、表格材料解读（行列对应、数据定位）、图形材料解读（柱状图、折线图、饼图解读），帮助考生快速准确定位数据信息。', '[]', '[]', '[]', '9课时', '', 0, 0, 0, '[]');
