INSERT INTO `what_course_categories` VALUES (606, 603, '图形材料解读', 'xingce_tuxing_cailiao', '', 'xingce', '', '#6366f1', '系统学习常识判断各模块，掌握政治、法律、历史、科技、地理等核心知识。', 30, 1, 3, '', 9, '2026-01-29 03:18:11.831', '2026-01-29 03:18:11.831', NULL, '常识判断是行测的综合性题型，主要考查考生的知识储备与综合素质。本课程体系涵盖政治常识（马克思主义、中特理论、时政热点）、法律常识（宪法、民法、刑法、行政法）、历史常识（中国史、世界史）、科技常识（科技成就、生活科学）、地理常识（自然地理、人文地理），帮助考生构建完整知识体系。', '[]', '[]', '[]', '3课时', '', 0, 0, 0, '[]');
