INSERT INTO `what_course_categories` VALUES (608, 607, '政治常识', 'xingce_zhengzhi_changshi', '', 'xingce', '', '#6366f1', '系统学习公共基础知识，涵盖政治、法律、经济、历史、地理、科技等多学科内容。', 10, 1, 2, '', 74, '2026-01-29 03:18:11.833', '2026-01-29 03:18:11.833', NULL, '公共基础知识是公考笔试的重要组成部分，主要考查考生的综合素质与知识储备。本课程体系涵盖政治理论（马克思主义哲学、中国特色社会主义理论、党史党建、时政热点）、法律法规（宪法、民法、刑法、行政法等）、经济管理、人文历史、地理科技等多学科内容，帮助考生全面提升公基答题能力。', '[]', '[]', '[]', '12课时', '', 0, 0, 0, '[]');
