INSERT INTO `what_course_categories` VALUES (617, 607, '其他常识', 'xingce_qita_changshi', '', 'xingce', '', '#6366f1', '系统学习常识判断，涵盖政治、法律、经济、历史、地理、科技等常考知识点。', 30, 1, 2, '', 73, '2026-01-29 03:18:11.848', '2026-01-29 03:18:11.848', NULL, '常识判断是行测考试的重要模块，主要考查考生对各学科基础知识的掌握程度。本课程体系涵盖政治常识、法律常识、经济常识、历史文化、地理环境、科技前沿等常考知识点，通过系统学习帮助考生构建完整的常识知识体系。', '[]', '[]', '[]', '20课时', '', 0, 0, 0, '[]');
