INSERT INTO `what_course_categories` VALUES (624, 623, '申论入门', 'shenlun_rumen', '', 'shenlun', '', '#6366f1', '系统学习申论考试，掌握归纳概括、综合分析、提出对策、贯彻执行、大作文五大题型的作答方法。', 10, 1, 2, '', 186, '2026-01-29 03:18:11.870', '2026-01-29 03:18:11.870', NULL, '申论是公务员考试的重要科目，主要考查考生的阅读理解能力、综合分析能力、提出和解决问题能力、文字表达能力。本课程体系涵盖归纳概括、综合分析、提出对策、贯彻执行、申发论述（大作文）五大题型，通过系统学习帮助考生全面提升申论作答能力。', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (625, 624, '申论入门精讲', 'shenlun_rumen_jingjiang', '', 'shenlun', '', '#6366f1', '系统学习申论归纳概括题型，掌握要点提取与归纳整合的方法。', 10, 1, 3, '', 16, '2026-01-29 03:18:11.871', '2026-01-29 03:18:11.871', NULL, '归纳概括是申论考试的基础题型，主要考查考生对材料信息的提取和归纳能力。本课程体系涵盖材料阅读方法（分层阅读、关键词标注）、要点提取技巧（直接摘抄、归纳概括）、答案整合方法（分类汇总、逻辑排序）等内容，帮助考生全面提升归纳概括能力。', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (626, NULL, '归纳概括课程', 'shenlun_guina', '', 'shenlun', 'FileText', 'from-blue-500 to-indigo-600', '提炼核心信息的能力', 20, 1, 1, '', 16, '2026-01-29 03:18:11.875', '2026-01-29 03:18:11.875', NULL, '', '[]', '[]', '[]', '', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (627, 626, '归纳概括方法', 'shenlun_guina_fangfa', '', 'shenlun', '', '#6366f1', '系统学习归纳概括题型，掌握要点提取、同类合并、规范表述等核心方法。', 10, 1, 2, '', 26, '2026-01-29 03:18:11.875', '2026-01-29 03:18:11.875', NULL, '归纳概括是申论的基础题型，主要考查考生对材料信息的提取与概括能力。本课程体系涵盖要点提取方法（关键词法、结构分析法）、要点整合技巧（同类合并、分类概括）、规范表述方法（条理清晰、语言精炼），帮助考生全面准确概括材料要点。', '[]', '[]', '[]', '18课时', '', 0, 0, 0, '[]');
