INSERT INTO `what_course_categories` VALUES (631, 630, '提出对策方法', 'shenlun_duice_fangfa', '', 'shenlun', '', '#6366f1', '系统学习提出对策题型，掌握对策来源分析、对策维度框架、可行性论证等核心方法。', 10, 1, 2, '', 26, '2026-01-29 03:18:11.884', '2026-01-29 03:18:11.884', NULL, '提出对策是申论的实务型题型，主要考查考生分析问题、解决问题的能力。本课程体系涵盖对策来源分析（直接对策、间接对策、自拟对策）、对策维度框架（主体、措施、保障等维度）、可行性论证（针对性、可操作性、有效性），帮助考生提出切实可行的对策建议。', '[]', '[]', '[]', '16课时', '', 0, 0, 0, '[]');
