INSERT INTO `what_course_categories` VALUES (635, 634, '综合分析题型', 'shenlun_fenxi_tixing', '', 'shenlun', '', '#6366f1', '系统学习综合分析题型，掌握评价分析、解释分析、启示分析等多种分析方法。', 10, 1, 2, '', 34, '2026-01-29 03:18:11.891', '2026-01-29 03:18:11.891', NULL, '综合分析是申论的思维型题型，主要考查考生的综合分析与判断能力。本课程体系涵盖评价分析（观点评价、现象评价）、解释分析（概念解释、句子理解）、启示分析（经验提炼、借鉴意义）、比较分析（异同分析、优劣比较），帮助考生深度理解材料内涵。', '[]', '[]', '[]', '18课时', '', 0, 0, 0, '[]');
