INSERT INTO `what_course_categories` VALUES (637, 635, '观点评价分析', 'shenlun_guandian_pingjia', '', 'shenlun', '', '#6366f1', '系统学习申论提出对策题型，掌握问题诊断与对策提出的方法。', 20, 1, 3, '', 8, '2026-01-29 03:18:11.893', '2026-01-29 03:18:11.893', NULL, '提出对策是申论考试的重要题型，主要考查考生发现问题、分析问题、解决问题的能力。本课程体系涵盖问题诊断方法（材料中直接对策、间接对策推导）、对策来源（政策依据、成功经验、问题反推）、答案规范（具体可行、针对性强）等内容。', '[]', '[]', '[]', '5课时', '', 0, 0, 0, '[]');
