INSERT INTO `what_course_categories` VALUES (640, NULL, '贯彻执行课程', 'shenlun_guanche', '', 'shenlun', 'FileCheck', 'from-orange-500 to-amber-600', '系统学习贯彻执行（应用文写作），掌握公文格式规范与各类应用文写作方法。', 50, 1, 1, '', 20, '2026-01-29 03:18:11.898', '2026-01-29 03:18:11.898', NULL, '贯彻执行是申论的实务型题型，主要考查考生的公文写作与执行能力。本课程体系涵盖公文格式规范（标题、称谓、正文、落款等要素）、各类应用文写作（讲话稿、倡议书、工作方案、调研报告、新闻稿等），帮助考生掌握规范的公文写作能力。', '[]', '[]', '[]', '', '', 0, 0, 0, '[]');
