INSERT INTO `what_course_categories` VALUES (643, 640, '各类公文写作', 'shenlun_gongwen_xiezuo', '', 'shenlun', '', '#6366f1', '系统学习申论大作文写作，掌握议论文的结构布局与论证方法。', 20, 1, 2, '', 65, '2026-01-29 03:18:11.900', '2026-01-29 03:18:11.900', NULL, '大作文写作是申论考试的压轴题型，主要考查考生的综合写作能力。本课程体系涵盖文章立意（准确把握题目要求）、结构布局（开头、主体、结尾）、论证方法（举例论证、对比论证、引用论证）、语言表达（规范准确、简洁有力）等核心内容。', '[]', '[]', '[]', '26课时', '', 0, 0, 0, '[]');
