INSERT INTO `what_course_categories` VALUES (649, 643, '其他文书', 'shenlun_qita_wenshu', '', 'shenlun', '', '#6366f1', '系统学习申论应用文写作，掌握各类公文的格式规范与写作技巧。', 60, 1, 3, '', 7, '2026-01-29 03:18:11.910', '2026-01-29 03:18:11.910', NULL, '应用文写作是申论考试的重要题型，主要考查考生的公文写作能力。本课程体系涵盖法定公文（通知、通报、报告、请示、函、纪要等）、事务文书（工作计划、总结、调研报告等）、应用文书（倡议书、建议书、讲话稿等）的格式规范与写作技巧。', '[]', '[]', '[]', '4课时', '', 0, 0, 0, '[]');
