INSERT INTO `what_course_categories` VALUES (651, 650, '文章写作技巧', 'shenlun_xiezuo_jiqiao', '', 'shenlun', '', '#6366f1', '系统学习大作文写作，掌握立意、结构、论证、语言等核心写作能力。', 10, 1, 2, '', 93, '2026-01-29 03:18:11.912', '2026-01-29 03:18:11.912', NULL, '大作文是申论的核心题型，主要考查考生的综合写作能力与政策理解水平。本课程体系涵盖审题立意（准确把握命题意图）、谋篇布局（科学安排文章结构）、论证方法（充实有力的论证）、语言表达（规范准确的政论语言），帮助考生写出高质量的申论大作文。', '[]', '[]', '[]', '30课时', '', 0, 0, 0, '[]');
