INSERT INTO `what_course_categories` VALUES (716, 715, '面试入门', 'mianshi_rumen', '', 'mianshi', '', '#6366f1', '系统学习公务员面试，掌握综合分析、组织计划、人际关系、应急应变、自我认知等各类题型的答题方法。', 10, 1, 2, '', 259, '2026-01-29 03:19:05.843', '2026-01-29 03:19:05.843', NULL, '公务员面试是公务员录用考试的重要环节，主要考查考生的综合分析能力、计划组织协调能力、人际交往能力、应变能力、言语表达能力等。本课程体系涵盖结构化面试各类题型（综合分析、组织计划、人际关系、应急应变、自我认知、情景模拟）以及无领导小组讨论的答题方法与技巧。', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (717, 716, '面试入门精讲', 'mianshi_rumen_jingjiang', '', 'mianshi', '', '#6366f1', '', 10, 1, 3, '', 7, '2026-01-29 03:19:05.843', '2026-01-29 03:19:05.843', NULL, '', '[]', '[]', '[]', '6课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (718, NULL, '综合分析题', 'mianshi_zonghefenxi', '', 'mianshi', 'Brain', 'from-blue-500 to-indigo-600', '社会现象、政策理解等', 20, 1, 1, '', 40, '2026-01-29 03:19:05.848', '2026-01-29 03:19:05.848', NULL, '', '[]', '[]', '[]', '', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (719, 718, '综合分析题型', 'mianshi_zonghefenxi_tixing', '', 'mianshi', '', '#6366f1', '系统学习综合分析类面试题型，掌握社会现象、政策理解、观点评价等分析方法。', 10, 1, 2, '', 68, '2026-01-29 03:19:05.849', '2026-01-29 03:19:05.849', NULL, '综合分析是结构化面试的核心题型，主要考查考生的综合分析能力与政治素养。本课程体系涵盖社会现象分析（热点事件分析）、政策理解分析（政策解读与评价）、观点评价分析（名言警句与观点辨析）、哲理分析（寓言故事与原理效应），帮助考生展现深度思考能力。', '[]', '[]', '[]', '20课时', '', 0, 0, 0, '[]');
