INSERT INTO `what_course_categories` VALUES (725, 724, '计划组织题型', 'mianshi_jihuazuzhi_tixing', '', 'mianshi', '', '#6366f1', '系统学习组织计划类面试题型，掌握活动策划、调研组织、协调安排等实务能力。', 10, 1, 2, '', 40, '2026-01-29 03:19:05.862', '2026-01-29 03:19:05.862', NULL, '组织计划是结构化面试的实务型题型，主要考查考生的组织协调与统筹能力。本课程体系涵盖活动策划（会议、培训、宣传等活动）、调研组织（调查研究的方法与流程）、协调安排（资源调配与任务分解）、突发处理（活动中的意外应对），帮助考生展现实际工作能力。', '[]', '[]', '[]', '18课时', '', 0, 0, 0, '[]');
INSERT INTO `what_course_categories` VALUES (726, 725, '调研类', 'mianshi_diaoyan_lei', '', 'mianshi', '', '#6366f1', '系统学习面试组织计划题型，掌握调研、宣传、活动策划等题目的作答方法。', 10, 1, 3, '', 11, '2026-01-29 03:19:05.862', '2026-01-29 03:19:05.862', NULL, '组织计划是面试考试的重要题型，主要考查考生的组织协调能力和计划能力。本课程体系涵盖调研类（调研设计、实施、报告）、宣传类（宣传策划、形式选择）、活动类（活动策划、组织协调）、会议类（会议筹备、流程安排）等题型的作答方法与技巧。', '[]', '[]', '[]', '5课时', '', 0, 0, 0, '[]');
