INSERT INTO `what_course_categories` VALUES (733, NULL, '应急应变题', 'mianshi_yingji', '', 'mianshi', 'AlertTriangle', 'from-orange-500 to-amber-600', '系统学习人际关系类面试题型，掌握与领导、同事、群众沟通协调的方法技巧。', 50, 1, 1, '', 24, '2026-01-29 03:19:05.878', '2026-01-29 03:19:05.878', NULL, '人际关系是结构化面试的情境型题型，主要考查考生的沟通协调与人际交往能力。本课程体系涵盖与领导相处（请示汇报、意见分歧）、与同事相处（工作配合、矛盾处理）、与群众相处（接待服务、矛盾化解），帮助考生展现情商与协调能力。', '[]', '[]', '[]', '', '', 0, 0, 0, '[]');
