INSERT INTO `what_fenbi_parse_tasks` VALUES (2, 14, '463774578398208', '西秀区2026年教育系统“西部之秀雁归助飞”教师选调公告', 'https://www.fenbi.com/page/exam-information-detail/463774578398208', 'completed', '解析完成，提取 19 个岗位', '{\"steps\": [{\"name\": \"提取粉笔原文链接\", \"status\": \"success\", \"details\": \"粉笔ID: 463774578398208\\n标题: \\n原文短链接: https://t.fenbi.com/s/00Bfnq\", \"message\": \"成功提取原文链接: https://t.fenbi.com/s/00Bfnq\", \"duration_ms\": 439}, {\"name\": \"解析短链接\", \"status\": \"success\", \"details\": \"短链接: https://t.fenbi.com/s/00Bfnq\\n最终URL: https://www.xixiu.gov.cn/web2023/zwgk/zfxxgk/fdzdgknr/rsxx/kkzp/202601/t20260123_89329365.html\", \"message\": \"成功解析短链接\", \"duration_ms\": 578}, {\"name\": \"获取页面内容\", \"status\": \"success\", \"details\": \"内容长度: 11038 字符\\n发现附件: 4 个\", \"message\": \"成功获取页面，标题: 西秀区2026年教育系统“西部之秀 雁归助飞”教师选调公告\", \"duration_ms\": 345}, {\"name\": \"下载解析附件\", \"status\": \"success\", \"details\": \"- 附件1：西秀区2026年教育系统“归雁计划”教师选调岗位计划表.xlsx (excel): 成功，提取 3382 字符\\n- 附件2：西秀区2026年教育系统“归雁计划”教师选调报名登记表.xlsx (excel): 成功，提取 1291 字符\\n- 附件3：西秀区2026年教育系统“归雁计划”教师选调工作证明.docx (word): 成功，提取 792 字符\\n\", \"message\": \"处理 3 个附件，成功 3 个，失败 0 个\", \"duration_ms\": 395}, {\"name\": \"LLM智能分析\", \"status\": \"success\", \"details\": \"摘要: 西秀区2026年教育系统启动“归雁计划”教师选调工作，旨在引导西秀区籍或配偶在西秀区机关事业单位工作的外地在编教师回乡建功立业。本次共计划选调公办学校在职在编教师19名，涉及全区15个教育单位，涵盖学前、小学、初中、高中及特殊教育岗位。报名采用现场报名方式，时间为2026年1月26日至2月6日。考试评价以面试（说课）为主，重点考核教师的综合素质、业务水平和专业素养。\\n\\n提取职位数: 19\\n- 学前教育教师岗位 (安顺市西秀区七眼桥镇七眼桥幼儿园)\\n- 学前教育教师岗位 (安顺市西秀区旧州镇旧州幼儿园)\\n- 学前教育教师岗位 (安顺市西秀区双堡镇双堡幼儿园)\\n...还有 16 个职位\\n\\n考试类型: 教师选调（归雁计划）\\n报名截止: 2026-02-06\\n\", \"message\": \"分析完成，置信度: 95%，提取职位: 19 个\", \"duration_ms\": 23796}, {\"name\": \"保存到数据库\", \"status\": \"success\", \"message\": \"已保存解析结果到数据库\", \"duration_ms\": 13}, {\"name\": \"提取列表页URL\", \"status\": \"skipped\", \"details\": \"尝试了多种策略(URL分析、HTML链接、LLM)，但未找到包含当前文章链接的上级页面\", \"message\": \"DFS搜索未找到包含当前文章的列表页\", \"duration_ms\": 23773}]}', '{\"success\": true, \"summary\": \"西秀区2026年教育系统启动“归雁计划”教师选调工作，旨在引导西秀区籍或配偶在西秀区机关事业单位工作的外地在编教师回乡建功立业。本次共计划选调公办学校在职在编教师19名，涉及全区15个教育单位，涵盖学前、小学、初中、高中及特殊教育岗位。报名采用现场报名方式，时间为2026年1月26日至2月6日。考试评价以面试（说课）为主，重点考核教师的综合素质、业务水平和专业素养。\", \"exam_info\": {\"exam_date\": \"待定\", \"exam_type\": \"教师选调（归雁计划）\", \"registration_end\": \"2026-02-06\", \"registration_start\": \"2026-01-26\"}, \"final_url\": \"https://www.xixiu.gov.cn/web2023/zwgk/zfxxgk/fdzdgknr/rsxx/kkzp/202601/t20260123_89329365.html\", \"positions\": [{\"major\": [\"学前教育\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"学前教育教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市西秀区七眼桥镇七眼桥幼儿园\", \"political_status\": \"不限\"}, {\"major\": [\"学前教育\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"学前教育教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市西秀区旧州镇旧州幼儿园\", \"political_status\": \"不限\"}, {\"major\": [\"学前教育\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"学前教育教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市西秀区双堡镇双堡幼儿园\", \"political_status\": \"不限\"}, {\"major\": [\"语文\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"小学语文教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市第五小学\", \"political_status\": \"不限\"}, {\"major\": [\"信息技术\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"小学信息技术教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市第九小学\", \"political_status\": \"不限\"}, {\"major\": [\"数学\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"小学数学教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市西秀区第十五小学\", \"political_status\": \"不限\"}, {\"major\": [\"语文\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"小学语文教师岗位\", \"recruit_count\": 1, \"work_location\": \"安顺市西秀区\", \"department_name\": \"安顺市西秀区启新学校\", \"political_status\": \"不限\"}, {\"major\": [\"美术\"], \"education\": \"大学本科及以上学历\", \"position_name\": \"小学美术教师岗位\", \"r